                return this;
            }
        }
        const props = { a: 'es-toolkit' };
        const d = () => 1;
        const a = new A(props, 1, 2, d);
        const b = cloneDeep(a);
        a.props.a = 'es-toolkit-2';
        expect(a).not.toBe(b);
        // @ts-expect-error: test
        expect(b['#b']).toBe(undefined);
        expect(b).toEqual({
            props: { a: 'es-toolkit' },
            d,
            c: 2,
        });
        expect(b.getA()).toEqual({ a: 'es-toolkit' });
}
}
}

